import { TruncatePipe } from './truncate.pipe';

describe('TruncatePipe', () => {
  const pipe = new TruncatePipe();

  it('should not truncate short strings', () => {
    expect(pipe.transform('Hello', 10)).toBe('Hello');
  });

  it('should truncate long strings and append "..."', () => {
    expect(pipe.transform('This is a long string', 10)).toBe('This is a ...');
  });

  it('should return empty string for null value', () => {
    expect(pipe.transform(null)).toBe('');
  });
});

// Create a test host component
@Component({
  template: '<p appHighlight>Test</p>'
})
class TestHostComponent {}

describe('HighlightDirective', () => {
  let fixture: ComponentFixture<TestHostComponent>;
  beforeEach(() => {
    TestBed.configureTestingModule({
      declarations: [TestHostComponent, HighlightDirective]
    });
    fixture = TestBed.createComponent(TestHostComponent);
    fixture.detectChanges();
  });

  it('should apply yellow background on mouseenter', () => {
    const el = fixture.nativeElement.querySelector('p');
    el.dispatchEvent(new MouseEvent('mouseenter'));
    fixture.detectChanges();
    expect(el.style.backgroundColor).toBe('yellow');
  });
});
